  "{x}, level {n}, learnt with {y}. {z}": ["{x}、レベル{n}、{y}で習得。{z}", "{x}, 레벨 {n}, {y}에서 배움. {z}", "{x},{n} 级,通过{y}习得。{z}", "{x},{n} 級,透過{y}習得。{z}", "{x}, cấp {n}, học qua {y}. {z}", "{x}, level {n}, dipelajari lewat {y}. {z}", "{x} ระดับ {n} เรียนจาก{y} {z}", "{x}, seviye {n}, {y} ile öğrenilir. {z}", "{x}, nivel {n}, se aprende con {y}. {z}", "{x}, nível {n}, aprendido com {y}. {z}", "{x}, уровень {n}, изучается в «{y}». {z}", "{x}, рівень {n}, вивчається в «{y}». {z}"],
